<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-foundations"><h4 id="topic-twentyseven-foundations"><?php echo s($bindtext('Herbs that stabilize and bind: general introduction', 'Hierbas que estabilizan y contienen: introducción general')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bindtext('The Board question is not simply “what stops leakage?” First identify what is escaping, whether the pattern is truly deficient and whether closing the exit would trap a pathogen.', 'La pregunta Board no es solo “¿qué detiene la fuga?”. Primero identifica qué escapa, si el patrón es realmente deficiente y si cerrar la salida atraparía un patógeno.')); ?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($bindtext('Lung chimney', 'Chimenea de Pulmón')); ?></strong><span>Wu Mei · Wu Wei Zi · He Zi</span></div><div><strong><?php echo s($bindtext('Sweat windows', 'Ventanas de sudor')); ?></strong><span>Wu Wei Zi · Fu Xiao Mai</span></div><div><strong><?php echo s($bindtext('Bowel door', 'Puerta intestinal')); ?></strong><span>Wu Mei · He Zi · Rou Dou Kou · Lian Zi · Chun Pi</span></div><div><strong><?php echo s($bindtext('Kidney vault', 'Bóveda de Riñón')); ?></strong><span>Shan Zhu Yu · Wu Wei Zi · Lian Zi · Lian Xu</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($bindtext('Inspect the house before locking its nine doors.', 'Inspecciona la casa antes de cerrar sus nueve puertas.')); ?></p><p><?php echo s($bindtext('Wu Mei closes Lung and bowel and chases worms. Wu Wei Zi carries five keys. He Zi leaves a throat microphone. Fu Xiao Mai absorbs sweat at the Heart window. Rou Dou Kou is the warm bowel cork; Chun Pi the cold Damp-Heat squeegee. Lian Zi rebuilds the Spleen floor, Lian Xu seals the Essence outlet and Shan Zhu Yu fills the Kidney vault while tightening its valve.', 'Wu Mei cierra Pulmón/intestino y persigue gusanos. Wu Wei Zi lleva cinco llaves. He Zi deja micrófono en garganta. Fu Xiao Mai absorbe sudor en la ventana del Corazón. Rou Dou Kou es corcho intestinal tibio; Chun Pi, secador frío de Humedad-Calor. Lian Zi reconstruye Bazo, Lian Xu sella Esencia y Shan Zhu Yu llena la bóveda del Riñón mientras aprieta su válvula.')); ?></p></aside><p class="single-herbs-guide__safety"><strong><?php echo s($bindtext('Never lock in the thief:', 'Nunca encierres al ladrón:')); ?></strong> <?php echo s($bindtext('Do not astringe acute Exterior disease, Phlegm obstruction, food stagnation, Damp-Heat diarrhea, painful urination or another unresolved excess.', 'No contener Exterior agudo, obstrucción por Flema, alimentos, diarrea por Humedad-Calor, micción dolorosa u otro exceso no resuelto.')); ?></p><ol class="single-herbs-guide__category-herbs"><?php foreach ($bindherbs as $h): ?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($h['name']); ?><?php echo isset($h['alias']) ? s(' / ' . $h['alias']) : ''; ?></strong><em><?php echo s($h['latin']); ?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($bindtext('Current category list', 'Lista vigente de la categoría')); ?></span></div><p><?php echo s($h['identity']); ?></p></li><?php endforeach; ?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-yang"><h4 id="topic-twentyseven-yang"><?php echo s($bindtext('Yang comparative fingerprints', 'Huellas comparativas de Yang')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bindtext('Relative study indices—not doses or efficacy percentages. Values were read directly from Yang figures 15.1–15.5; only exact current-list entries are graphed.', 'Índices relativos—no dosis ni porcentajes. Valores leídos directamente de figuras 15.1–15.5 de Yang; solo se grafican entradas exactas de la lista actual.')); ?></p><div class="single-herbs-guide__yang-charts"><?php foreach ($bindcharts as $chart): ?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]); ?></h5><small><?php echo s($chart[1]); ?></small><?php foreach ($chart[2] as $name => $value): ?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name); ?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo (int)$value; ?>%"></span></span><b><?php echo (int)$value; ?></b></div><?php endforeach; ?></article><?php endforeach; ?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($bindtext('Do not let ties erase identity:', 'No dejes que los empates borren identidad:')); ?></strong> <?php echo s($bindtext('Wu Mei, Wu Wei Zi and He Zi all score 100 for Lung containment, but worms/thirst, sweat/Essence/Shen and throat/voice separate them.', 'Wu Mei, Wu Wei Zi y He Zi puntúan 100 para Pulmón, pero gusanos/sed, sudor/Esencia/Shen y garganta/voz las separan.')); ?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-profiles"><h4 id="topic-twentyseven-profiles"><?php echo s($bindtext('Individual herb profiles', 'Perfiles individuales de las hierbas')); ?></h4><div class="single-herbs-guide__profiles"><?php foreach ($bindherbs as $h): ?><details class="single-herbs-guide__profile"<?php echo $h['name'] === 'Wu Wei Zi' ? ' open' : ''; ?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($h['name']); ?><?php echo isset($h['alias']) ? s(' / ' . $h['alias']) : ''; ?></span><span class="single-herbs-guide__profile-latin"><?php echo s($h['latin']); ?></span><span class="single-herbs-guide__profile-meta"><?php echo s($h['properties']); ?> · <?php echo s($h['channels']); ?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($bindtext('Study dose', 'Dosis de estudio')); ?></dt><dd><?php echo s($h['dose']); ?></dd><dt><?php echo s($bindtext('Identity', 'Identidad')); ?></dt><dd><?php echo s($h['identity']); ?></dd><dt><?php echo s($bindtext('Exam clue', 'Pista de examen')); ?></dt><dd><?php echo s($h['clue']); ?></dd><dt><?php echo s($bindtext('Memory', 'Memoria')); ?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($h['memory']); ?></dd><dt><?php echo s($bindtext('Unique fingerprint', 'Huella única')); ?></dt><dd><?php echo s($h['unique']); ?></dd><dt><?php echo s($bindtext('Formula boundary', 'Límite de fórmulas')); ?></dt><dd class="single-herbs-guide__profile-formulas"><?php echo s($bindtext('No chief or co-chief role in the current 63-formula Board roster. Ingredient appearances are not promoted as chief-herb links.', 'No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas. La aparición como ingrediente no se presenta como enlace principal.')); ?></dd><dt><?php echo s($bindtext('Safety', 'Seguridad')); ?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($h['caution']); ?></dd></dl></div></details><?php endforeach; ?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-comparisons"><h4 id="topic-twentyseven-comparisons"><?php echo s($bindtext('High-yield comparisons', 'Comparaciones de alto rendimiento')); ?></h4><div class="single-herbs-guide__comparisons"><?php foreach ($bindcomparisons as $c): ?><?php $url = new moodle_url($ises ? $c[1] : $c[0], ['from' => 'single-herbs', 'focus' => (string)$selected['number']]); ?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false); ?>"><strong><?php echo s($c[2]); ?></strong><span><?php echo s($c[3]); ?></span><small><?php echo s($bindtext('Open full comparison →', 'Abrir comparación completa →')); ?></small></a><?php endforeach; ?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-questions"><h4 id="topic-twentyseven-questions"><?php echo s($bindtext('Yang questions shown in full', 'Preguntas de Yang mostradas completas')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($bindtext('Chapter 15 questions 1–7 define the category. Herbs outside the current category list are explicitly identified.', 'Las preguntas 1–7 del capítulo 15 definen la categoría. Las hierbas fuera de la lista actual se identifican expresamente.')); ?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($bindtext('Card', 'Tarjeta')); ?>" data-of-label="<?php echo s($bindtext('of', 'de')); ?>"><?php foreach ($bindquestions as $i => $q): ?><article class="single-herbs-guide__yang-card<?php echo $i === 0 ? ' is-active' : ''; ?>" data-yang-card aria-hidden="<?php echo $i === 0 ? 'false' : 'true'; ?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($bindtext('Question', 'Pregunta')); ?> <?php echo $i + 1; ?> <?php echo s($bindtext('of', 'de')); ?> <?php echo count($bindquestions); ?> · Yang, <?php echo s($bindtext('Chapter', 'capítulo')); ?> 15</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]); ?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($bindtext('Answer', 'Respuesta')); ?> <?php echo $i + 1; ?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]); ?></p></div></article><?php endforeach; ?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($bindtext('Previous', 'Anterior')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($bindtext('Show answer', 'Mostrar respuesta')); ?>" data-hide-label="<?php echo s($bindtext('Show question', 'Mostrar pregunta')); ?>"><?php echo s($bindtext('Show answer', 'Mostrar respuesta')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($bindtext('Next', 'Siguiente')); ?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($bindtext('Card', 'Tarjeta')); ?> 1 <?php echo s($bindtext('of', 'de')); ?> <?php echo count($bindquestions); ?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyseven-recall"><h4 id="topic-twentyseven-recall"><?php echo s($bindtext('Quick recall', 'Repaso rápido')); ?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($bindtext('Five locks in one berry?', '¿Cinco cerraduras en una baya?')); ?></summary><p><strong>Wu Wei Zi.</strong></p></details><details><summary><?php echo s($bindtext('Roundworms plus Lung/bowel leakage?', '¿Áscaris más fuga de Pulmón/intestino?')); ?></summary><p><strong>Wu Mei.</strong></p></details><details><summary><?php echo s($bindtext('Throat and voice decide?', '¿Deciden garganta y voz?')); ?></summary><p><strong>He Zi.</strong></p></details><details><summary><?php echo s($bindtext('Warm cork for cold chronic diarrhea?', '¿Corcho tibio para diarrea fría crónica?')); ?></summary><p><strong>Rou Dou Kou.</strong></p></details><details><summary><?php echo s($bindtext('Cold Damp-Heat squeegee—listed as Chuan Pi?', '¿Secador frío de Humedad-Calor—listado como Chuan Pi?')); ?></summary><p><strong>Chun Pi / Chuan Pi.</strong></p></details><details><summary><?php echo s($bindtext('Spleen floor versus direct Essence seal?', '¿Piso de Bazo frente a sello directo de Esencia?')); ?></summary><p><strong>Lian Zi</strong> / <strong>Lian Xu.</strong></p></details><details><summary><?php echo s($bindtext('Food-like cool herb for both kinds of sweat?', '¿Hierba fresca/alimenticia para ambos sudores?')); ?></summary><p><strong>Fu Xiao Mai.</strong></p></details><details><summary><?php echo s($bindtext('Tonifies the reservoir while tightening its valve?', '¿Tonifica el depósito mientras aprieta la válvula?')); ?></summary><p><strong>Shan Zhu Yu.</strong></p></details></div></section>

